import sys

def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        R = int(next(iterator))

        current_rating = R

        for _ in range(N):
            D = int(next(iterator))
            A = int(next(iterator))

            # Determine if rating update happens based on current rating and division
            # Div 1: 1600 <= rating <= 2799
            # Div 2: 1200 <= rating <= 2399

            updated = False
            if D == 1:
                if 1600 <= current_rating <= 2799:
                    updated = True
            else:
                # Div 2
                if 1200 <= current_rating <= 2399:
                    updated = True

            if updated:
                current_rating += A

        print(current_rating)

    except StopIteration:
        pass

if __name__ == '__main__':
    solve()
